    /** «hace 5 min», «ayer», o la fecha si ya queda lejos. */
    haceCuanto(iso) {
      if (!iso) return "";
      const min = Math.floor((Date.now() - Date.parse(iso)) / 6e4);
      if (!isFinite(min)) return "";
      const T2 = (x2) => this.trStr(x2);
      const junta = (n2, patron) => T2(patron).replace("{n}", n2);
      if (min < 2) return T2("ahora mismo");
      if (min < 60) return junta(min, "hace {n} min");
      const h = Math.floor(min / 60);
      if (h < 24) return junta(h, "hace {n} h");
      const d = Math.floor(h / 24);
      if (d === 1) return T2("ayer");
      if (d < 7) return junta(d, "hace {n} días");
      return this.fechaCorta(iso);
    }
