             style="position:absolute;top:0;left:0;right:0;bottom:var(--teclado, 0px);z-index:36;display:flex;flex-direction:column;background:{{ tema.bg }};background-image:{{ tema.patron }};transform:translateX({{ panelX }});transition:{{ panelTrans }};animation:{{ panelAnim }};box-shadow:-14px 0 34px oklch(0.24 0.05 90 / 0.18)">
          <div style="height:env(safe-area-inset-top);min-height:0;background:{{ tema.bg }}"></div>
