            <button onClick="{{ volverSeccion }}" aria-label="{{ panelVolverA }}" style="width:40px;height:40px;flex:none;border:none;border-radius:50%;background:{{ panelBotonBg }};cursor:pointer;color:{{ tema.tinta }};display:flex;align-items:center;justify-content:center">
              <svg viewBox="0 0 24 24" style="width:20px;height:20px" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5l-7 7 7 7"></path></svg>
            </button>
